import csv

def validate_user(username, password, csv_file='users.csv'):
    """Check username/password against CSV file of credentials."""
    try:
        with open(csv_file, 'r') as f:
            reader = csv.DictReader(f)
            for row in reader:
                if row['username'] == username and row['password'] == password:
                    return True
        return False
    except FileNotFoundError:
        print(f"Credential file {csv_file} not found")
        return False

# Example usage
if __name__ == '__main__':
    test_user = 'admin'
    test_pass = 'ctf2024'
    if validate_user(test_user, test_pass):
        print(f"User {test_user} authenticated")
    else:
        print("Authentication failed")
